import { ref, watch } from 'vue'

export function useLocalStorage(key, initial) {
  const stored = ref(JSON.parse(localStorage.getItem(key)) ?? initial)

  watch(stored, (val) => {
    localStorage.setItem(key, JSON.stringify(val))
  }, { deep: true })

  return stored
}
